package com.bank.rotate.service;

import java.util.logging.Logger;

// Counts rotations = index of the minimum in a rotated sorted array.
public class RotationCountService {
    private static final Logger log = Logger.getLogger(RotationCountService.class.getName());

    public int countRotations(int[] serials) {
        int start = 0, end = serials.length - 1;
        while (start < end) {
            int mid = start + (end - start) / 2;
            if (serials[mid] > serials[end]) start = mid + 1; // min is to the right
            else end = mid;                                    // min is here or left
        }
        final int count = start; // index of minimum == rotation count
        log.info(() -> "Array rotated " + count + " times (min at index " + count + ")");
        return count;
    }
}
